package android.util;
public class LruCache<K,V>{final int max;int size;final java.util.LinkedHashMap<K,V> items=new java.util.LinkedHashMap<>(16,.75f,true);public LruCache(int m){max=m;}protected int sizeOf(K k,V v){return 1;}public synchronized V get(K k){return items.get(k);}public synchronized void put(K k,V v){V old=items.put(k,v);if(old!=null)size-=sizeOf(k,old);size+=sizeOf(k,v);while(size>max&&!items.isEmpty()){java.util.Map.Entry<K,V> first=items.entrySet().iterator().next();size-=sizeOf(first.getKey(),first.getValue());items.remove(first.getKey());}}public synchronized void evictAll(){items.clear();size=0;}}
